import{_ as a,a0 as l,w as n,s as i,ao as u,I as p,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"美國立法者提出一項保護開源軟件的新法案 | LCTT x X-CMD","titleTemplate":false,"description":"美國立法者提出一項保護開源軟件的新法案 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"美國立法者提出一項保護開源軟件的新法案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"美國立法者提出一項保護開源軟件的新法案 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software","title":"美國立法者提出一項保護開源軟件的新法案","tag":"202209","desc":""},"relativePath":"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software.md","filePath":"[post].md"}'),m={name:"202209/20220923 Lawmakers Proposes A New Bill To Protect Open Source Software.md"};function w(f,t,d,T,C,S){const o=l("Link");return n(),i("div",null,[t[15]||(t[15]=u('<h1 id="美國立法者提出一項保護開源軟件的新法案" tabindex="-1">美國立法者提出一項保護開源軟件的新法案 <a class="header-anchor" href="#美國立法者提出一項保護開源軟件的新法案" aria-label="Permalink to “美國立法者提出一項保護開源軟件的新法案”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/law-4-1536x1025.jpeg" alt=""></p><blockquote><p>美國的《保護開源軟件法案》將責成管理和預算辦公室提供有關如何安全使用開源軟件的説明。</p></blockquote><p>美國立法者週四提出了一項要求，美國網絡安全和基礎設施安全局（CISA）需創建風險框架以提高開源軟件安全性的措施。為了降低依賴開源代碼的系統風險，各機構將利用該框架，CISA 將決定關鍵基礎設施所有者和運營商是否也可以自願使用它。</p><p>大多數系統依賴於免費提供的並由社區維護的開源軟件來構建網站和應用程序；最大的用户之一是美國聯邦政府。該立法由美國國土安全委員會主席兼高級成員、俄亥俄州共和黨參議員 Sens. Rob Portman、R-Ohio 和 Gary Peters D-Mich 在一次聽證會後提出，以回應在開源代碼中發現的影響美國聯邦系統和全球數百萬其他系統的嚴重、廣泛的 Log4j 漏洞。</p><p>“這一事件對聯邦系統和關鍵基礎設施公司——包括銀行、醫院和公用事業公司——構成了嚴重威脅，美國人每天都依賴這些公司提供基本服務，”彼得斯在公告中説。“這項明智的兩黨立法將有助於保護開源軟件，並進一步加強我們的網絡安全防禦，防止網絡犯罪分子和外國對手對全國網絡發起的不斷的攻擊。”</p><p>這項《保護開源軟件法》還要求美國管理和預算辦公室為各機構發佈關於保護開源軟件的指南，在 CISA 網絡安全諮詢委員會中設立一個軟件安全小組委員會，並要求 CISA 聘請開源軟件專家協助處理網絡事件。</p><p>在此之前，Peters 和 Portman 的提議已獲得美國參議院一致通過並簽署成為法律，以加強州和地方政府的網絡防禦，並迫使關鍵基礎設施的所有者和運營商向 CISA 報告重大網絡攻擊和勒索軟件付款。</p><hr>',9)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/09/lawmakers-proposes-a-new-bill-to-protect-open-source-software/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/09/lawmakers-proposes-a-new-bill-to-protect-open-source-software/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/littlebirdnest"},{default:s(()=>[...t[4]||(t[4]=[e("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const L=a(m,[["render",w]]);export{k as __pageData,L as default};
